// Method 1: Recursion
class Solution {
    public List<Integer> rightSideView(TreeNode root) {
        List<Integer> res = new ArrayList<>();
        if (root == null) {
            return res;
        }
        helper(root, res, 0);
        return res;
    }

    private void helper(TreeNode curr, List<Integer> res, int level) {
        if (curr == null) {
            return;
        }
        // Magic rule.
        if (level == res.size()) {
            res.add(curr.val);
        }
        helper(curr.right, res, level + 1);
        helper(curr.left, res, level + 1);
    }
}

